const clamp01 = (value) => Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0));
export function projectileFootprintReleasePresentation(input, reducedMotion = false) { const pressure = clamp01(input.pressure), release = clamp01(input.release), reclaim = clamp01(release * (1 - pressure * .38)), floor = input.critical ? .8 : .5, max = input.critical ? .98 : .94, trailCeiling = (floor + (max - floor) * reclaim) * (reducedMotion ? .96 : 1); return { reclaim, canonicalBodyScale: 1, trailCeiling, presentationOnly: true }; }
export function telegraphSafeLaneFootprintReleasePresentation(input, reducedFlash = false) { const overlap = clamp01(input.overlap), release = clamp01(input.release), hold = clamp01(overlap * (1 - release * .6)), secondaryCeiling = Math.min(1, Math.max(.58, .66 + release * .22 - hold * .18)) * (reducedFlash ? .96 : 1); return { hold, telegraphEdgeScale: 1, safeLaneScale: 1, secondaryCeiling, presentationOnly: true }; }
export function impactFootprintReleasePresentation(input, reducedFlash = false) { const footprint = clamp01(Math.max(input.heroProximity, input.crowd * .92)), release = clamp01(input.release), reclaim = clamp01(release * (1 - footprint * .33)), floor = input.critical ? .56 : .32, max = input.critical ? .94 : 1, fillCeiling = (floor + (max - floor) * reclaim) * (reducedFlash ? .96 : 1), secondaryCeiling = Math.max(input.critical ? .62 : .5, .58 + .34 * reclaim) * (reducedFlash ? .97 : 1); return { footprint, reclaim, canonicalBodyScale: 1, fillCeiling, secondaryCeiling, presentationOnly: true }; }
export function specialistFootprintReleasePresentation(input, reducedMotion = false) { const hazard = clamp01(input.hazardPressure), recovery = clamp01(input.recovery), ownerHold = input.owner === 'recovery' ? 1 : input.owner === 'locomotion' ? .72 : input.owner === 'hit' ? .6 : .42, footprint = clamp01(hazard * .72 + ownerHold * .28), reclaim = clamp01(recovery * (1 - footprint * .38)), floor = input.owner === 'recovery' ? .54 : .58, max = input.owner === 'special' || input.owner === 'attack' ? .9 : .76, trailCeiling = (floor + (max - floor) * reclaim) * (reducedMotion ? .96 : 1); return { footprint, reclaim, canonicalBodyScale: 1, trailCeiling, presentationOnly: true }; }
export function footprintReleaseBudgetPresentation(input, reducedMotion = false, reducedFlash = false) { const pressure = clamp01(input.pressure), release = clamp01(input.release), critical = clamp01(Math.max(0, input.criticalCount) / 3), reclaim = clamp01(release * (1 - pressure * .3)), reserve = input.safeLaneVisible ? .08 : 0, secondaryCeiling = Math.max(.56, .58 + reclaim * .34 - critical * .04 - reserve) * (reducedMotion ? .98 : 1) * (reducedFlash ? .97 : 1); return { reclaim, criticalScale: 1, canonicalBodyScale: 1, safeLaneScale: 1, secondaryCeiling: clamp01(secondaryCeiling), presentationOnly: true }; }
